def full_guard():
    guard('training')
    with REG.open(encoding='utf-8-sig',newline='') as f:rows=list(csv.DictReader(f))
    denied={str(Path(r[k]).resolve()).lower() for r in rows if r['cohort']!='development' for k in ['reference','metadata'] if r.get(k)}
    external_roots=[Path('H:/RadarST_2_ExactMask_External_FULL_20261030'),Path('H:/RadarST_Next_CET_External_20261025'),ROOT/'external_predictions',ROOT/'external_evaluation']
    def hook(event,args):
        if event=='open' and isinstance(args[0],(str,bytes)):
            p=Path(os.fsdecode(args[0])).resolve();mode,flags=args[1:3];write=(isinstance(mode,str) and any(x in mode for x in 'wax+')) or bool(flags&(os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC))
            if not write and (str(p).lower() in denied or any(p.is_relative_to(q) for q in external_roots)):raise RuntimeError('EXTERNAL_DATA_IN_FULL_FIT '+str(p))
    sys.addaudithook(hook)

def get_lock():
    lock=js(ROOT/'configs/FULL_SELECTED_CANDIDATE_LOCK.json');assert lock['status']=='FROZEN_BEFORE_EXTERNAL'
    identity=js(ROOT/'audits/CROSS_COHORT_RAW_IDENTITY_ROUTE_AUDIT.json');assert identity['status']=='PASS' and not identity['severe_same_expression_and_spots'];assert sha(REG)==lock['registered_pair_manifest_sha256']
    source=ROOT/lock.get('selection_record','reports/ROUND1_DECISION.json')
    assert source in [ROOT/'reports/ROUND1_DECISION.json',ROOT/'round2_event_alignment/DECISION.json',ROOT/'round3_instance_quality/DECISION.json',ROOT/'round4_context_alignment/DECISION.json']
    d=js(source);assert d['status'] in ['CONTROLLED_VECTOR_GO','OBJECT_QUALITY_VECTOR_GO'] and d['selected_method']==lock['selected_method'] and lock['selected_method'] in d['eligible_methods'] and sha(source)==lock['dev_selection_sha256']
    for rel,h in lock['scientific_implementation_files'].items():assert sha(ROOT/rel)==h
    return lock

def true_targets(b,a,sizes,ari):
    delta=a-b;y=[]
    for kind in ['gain','harm','exact']:
        for lo,hi in [(1,2),(3,5),(6,10)]:
            m=(sizes>=lo)&(sizes<=hi)
            y.append(float(np.maximum(delta[m],0).sum()) if kind=='gain' else float(np.maximum(-delta[m],0).sum()) if kind=='harm' else float(((a[m]>=1-1e-12).astype(int)-(b[m]>=1-1e-12)).sum()))
    return y+[ari]

def prepare(J):
    full_guard();lock=get_lock();out=ROOT/'full_fit_targets'/J
    if (out/'FULL_CONTEXT_GATE.json').exists():
        g=js(out/'FULL_CONTEXT_GATE.json');assert sha(out/'CONTEXT.parquet')==g['target_sha256'];return
    assert not out.exists();out.mkdir(parents=True);v=Verify();modelroot=AF/'models_gpu'/J;mg=js(modelroot/'MODEL_GATE.json');v.check(modelroot/'MODEL_GATE.json');train=sorted({r['dataset'] for r in pairs()}-{J});assert sorted(mg['training_datasets'])==train
    weight=modelroot/'G_VALUE_UNARY.joblib';v.check(weight,mg['model_files'][weight.name]);bundle=joblib.load(weight);assert sorted(bundle['training_datasets'])==train and len(train)==11;del bundle
    upstream_table=pd.read_parquet(ROOT/'targets'/J/'UPSTREAM.parquet');parts=[];qa=[];sources={}
    for reg in [r for r in pairs() if r['dataset']==J and r['workflow'] in ['GraphST','Seurat']]:
        wf=reg['workflow'];c=load_map(J,wf);src=AF/'gpu_predictions'/J/wf/'G_VALUE_UNARY'
        for name in ['FINAL_LABELS.csv','SELECTED_OBJECTS.csv','SELECTION_GATE.json']:v.check(src/name)
        chosen=pd.read_csv(src/'SELECTED_OBJECTS.csv');S={c['lookup'][cid] for cid in chosen.candidate_id};current=labels_from(S,c['members'],c['a']['base']);old=pd.read_csv(src/'FINAL_LABELS.csv');assert old.spot_id.tolist()==list(c['a']['spots'])
        np.testing.assert_array_equal(pd.factorize(current)[0],pd.factorize(old.refined.to_numpy())[0])
        add=[c['lookup'][cid] for cid in upstream_table.loc[upstream_table.workflow.eq(wf),'candidate_id']];remove=[]
        for typ,g in chosen.groupby('proposal_type'):
            ids=sorted(g.candidate_id,key=lambda cid:hashlib.sha256(f'FULL|{J}|{wf}|remove|{cid}'.encode()).hexdigest());remove.extend(c['lookup'][cid] for cid in ids[:64])
        indices=add+remove;ops=[0]*len(add)+[1]*len(remove);dyn,feet,conf=dynamic_features(c,S,indices,ops,True);x=c['x'].iloc[indices].reset_index(drop=True).copy();genes=gene_evidence(c,J).iloc[indices].reset_index(drop=True)
        for k in dyn:x[k]=dyn[k].to_numpy()
        for k in genes:x[k]=genes[k].to_numpy()
        assert sha(reg['reference'])==reg['reference_sha256'];truth=pd.read_csv(reg['reference'],dtype=str,keep_default_na=False).set_index('spot_id').truth_label.reindex(c['a']['spots']);assert truth.notna().all();ev=ObjectEvaluator(truth.to_numpy(),c['adj']);reference_sets=[maskof(s) for s in ev.refs];engine=InterventionEngine(current,c['adj'],reference_sets);upstream=InterventionEngine(c['a']['base'],c['adj'],reference_sets).baseline;ari0=information_metrics(truth.to_numpy(),current)['ARI'];rows=[]
        from event_round2 import EY,event_delta
        for k,(i,op) in enumerate(zip(indices,ops)):
            after=S-conf[k]
            if not op:after.add(i)
            labels=current.copy()
            for oldi in conf[k]:labels[c['members'][oldi]]=c['a']['base'][c['members'][oldi]]
            if not op:labels[c['members'][i]]=int(current.max())+1
            q=engine.apply(labels,check=k in [0,len(add)]);ys=true_targets(engine.baseline,q,ev.sizes,information_metrics(truth.to_numpy(),labels)['ARI']-ari0);row=x.iloc[k].to_dict();row.update(dataset=J,workflow=wf,candidate_id=c['ids'][i],context=3,regime='onpolicy',operation_remove=op);row.update(dict(zip(Y,ys)));row.update(dict(zip(EY,event_delta(engine.baseline,q,upstream,ev.sizes))));rows.append(row)
        parts.append(pd.DataFrame(rows));qa.append(dict(workflow=wf,full_partition_checks=[0,len(add)],rows=len(rows)));sources[wf]=dict(generator_training_datasets=train,heldout_receiver=J,generator_model_sha256=sha(weight),selected_state_sha256=sha(src/'SELECTED_OBJECTS.csv'))
        print('FULL_CONTEXT_PREPARED',J,wf,len(rows),flush=True)
    table=pd.concat(parts,ignore_index=True);table.to_parquet(out/'CONTEXT.parquet',index=False);put(out/'FULL_CONTEXT_GATE.json',dict(status='PASS',dataset=J,receiver_excluded_from_generator=True,external_labels_or_data_read=False,routes=sources,checks=qa,source_files=v.checked,target_sha256=sha(out/'CONTEXT.parquet'),selection_lock_sha256=sha(ROOT/'configs/FULL_SELECTED_CANDIDATE_LOCK.json'),utc=utc()))

def fit(threads):
    full_guard();lock=get_lock();name=lock['model_family'];train=sorted({r['dataset'] for r in pairs()});parts=[];sources={};physical={}
    for J in train:
        for p,gname in [(ROOT/'targets'/J/'UPSTREAM.parquet','UPSTREAM_GATE.json'),(ROOT/'full_fit_targets'/J/'CONTEXT.parquet','FULL_CONTEXT_GATE.json')]:
            g=js(p.parent/gname);assert g['status']=='PASS' and sha(p)==g['target_sha256'];t=pd.read_parquet(p);assert set(t.dataset)=={J};parts.append(t);sources[str(p)]=sha(p)
            if gname=='FULL_CONTEXT_GATE.json':assert g['receiver_excluded_from_generator'] and not g['external_labels_or_data_read']
        identity=pd.read_parquet(ROOT/'inputs'/J/'GraphST'/'CANDIDATES.parquet');physical.update({cid:hashlib.sha256(';'.join(sorted(m.split(';'))).encode()).hexdigest() for cid,m in zip(identity.candidate_id,identity.member_spots)})
    table=pd.concat(parts,ignore_index=True);y=table[Y].to_numpy(np.float32);good=np.isfinite(y).all(1);invalid=int((~good).sum());table=table.loc[good].reset_index(drop=True);y=y[good];ph=table.candidate_id.map(physical);assert ph.notna().all();keys=table[['dataset','regime','workflow','operation_remove']].astype(str).agg('|'.join,axis=1)+'|'+ph;counts=keys.value_counts();w=keys.map(lambda k:1/counts[k]).to_numpy()
    for groupcols in [['dataset','regime','workflow'],['dataset','regime'],['dataset']]:
        k=table[groupcols].astype(str).agg('|'.join,axis=1);w/=pd.Series(w).groupby(k.to_numpy()).transform('sum').to_numpy()
    w*=len(w)/w.sum();scale=np.sqrt(np.average((y-np.average(y,axis=0,weights=w))**2,axis=0,weights=w));scale[:9]=np.maximum(scale[:9],.01);scale[9]=max(scale[9],1e-8)
    cols=js(ROOT/'models'/train[0]/name/'MODEL_GATE.json')['columns']
    for J in train:assert js(ROOT/'models'/J/name/'MODEL_GATE.json')['columns']==cols
    x=table[cols].to_numpy(np.float32);assert np.isfinite(x).all();model=ExtraTreesRegressor(n_estimators=256,min_samples_leaf=8,max_features=.7,n_jobs=threads,random_state=20261104,bootstrap=False);model.fit(x,y/scale,sample_weight=w);model.n_jobs=1;out=ROOT/'full_fit_models'/name;out.mkdir(parents=True,exist_ok=False);joblib.dump(dict(model=model,columns=cols,targets=Y,scale=scale,heldout='EXTERNAL_COHORT',training_datasets=train),out/'MODEL.joblib',compress=3);put(out/'MODEL_GATE.json',dict(status='PASS',training_datasets=train,rows=len(table),invalid_target_rows_excluded=invalid,model_family=name,columns=cols,model_sha256=sha(out/'MODEL.joblib'),input_hashes=sources,external_data_or_outcomes_read=False,selection_fixed_before_external=True,utc=utc()));print('FULL_FITTED',name,len(table),flush=True)

if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--prepare');ap.add_argument('--fit',action='store_true');ap.add_argument('--threads',type=int,default=4);a=ap.parse_args();assert bool(a.prepare)!=a.fit
